script:
frappe.ui.form.on("Sales Invoice Item", {

    barcode_scan: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row.barcode_scan) return;

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Item Barcode",
                filters: {
                    barcode: row.barcode_scan
                },
                fields: ["parent", "uom"]
            },

            callback: function(r) {

                if (r.message && r.message.length) {

                    let d = r.message[0];

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "item_code",
                        d.parent
                    );

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "uom",
                        d.uom
                    );

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "qty",
                        1
                    );

                    frm.refresh_field("items");
                }
            }
        });
    }
});

frappe.ui.form.on('Sales Invoice Item', {
	refresh(frm) {
		// your code here
	}
})

frappe.ui.form.on('Sales Invoice Item', {
	refresh(frm) {
		// your code here
	}
})

frappe.ui.form.on("Item", {
	last_purchase_rate(frm) {
		fill_empty_packing_purchase_rates(frm);
	},
	custom_default_purchase_rate(frm) {
		fill_empty_packing_purchase_rates(frm);
	},
});

frappe.ui.form.on("Retail Packing Detail", {
	conversion_factor(frm, cdt, cdn) {
		set_default_packing_purchase_rate(frm, cdt, cdn);
	},
	custom_retail_packing_detail_add(frm, cdt, cdn) {
		set_default_packing_purchase_rate(frm, cdt, cdn);
	},
});

function get_packing_base_purchase_rate(frm) {
	return flt(frm.doc.custom_default_purchase_rate || frm.doc.last_purchase_rate);
}

function set_default_packing_purchase_rate(frm, cdt, cdn) {
	const row = locals[cdt][cdn];
	if (flt(row.purchase_rate)) return;

	const base_rate = get_packing_base_purchase_rate(frm);
	if (!base_rate) return;

	frappe.model.set_value(
		cdt,
		cdn,
		"purchase_rate",
		base_rate * flt(row.conversion_factor || 1)
	);
}

function fill_empty_packing_purchase_rates(frm) {
	(frm.doc.custom_retail_packing_detail || []).forEach((row) => {
		if (!flt(row.purchase_rate)) {
			set_default_packing_purchase_rate(frm, row.doctype, row.name);
		}
	});
}

frappe.ui.form.on('Item', {
    custom_warranty: function(frm) {
        if (!frm.doc.custom_warranty) {
            frm.set_value('custom_in_months', null);
        }
    }
});

frappe.ui.form.on("Item", {
    validate(frm) {
        remove_empty_barcode_rows(frm);
    },
    before_save(frm) {
        remove_empty_barcode_rows(frm);
    }
});

function remove_empty_barcode_rows(frm) {
    if (!Array.isArray(frm.doc.barcodes) || !frm.doc.barcodes.length) return;

    let removed = false;
    for (let i = frm.doc.barcodes.length - 1; i >= 0; i--) {
        const row = frm.doc.barcodes[i];
        if (row.barcode) continue;

        if (row.doctype && row.name) {
            frappe.model.clear_doc(row.doctype, row.name);
        }
        frm.doc.barcodes.splice(i, 1);
        removed = true;
    }

    if (removed) {
        frm.refresh_field("barcodes");
    }
}

frappe.ui.form.on("Purchase Order Item", {
	qty(frm, cdt, cdn) {
		set_balance_qty(cdt, cdn);
	},
	received_qty(frm, cdt, cdn) {
		set_balance_qty(cdt, cdn);
	}
});

function set_balance_qty(cdt, cdn) {
	const row = locals[cdt][cdn];
	frappe.model.set_value(cdt, cdn, "balance_qty", flt(row.qty) - flt(row.received_qty));
}

frappe.ui.form.on("Item", {
	refresh(frm) {
		hide_item_arabic_translate_button(frm);
		setTimeout(() => hide_item_arabic_translate_button(frm), 0);
	}
});

function hide_item_arabic_translate_button(frm) {
	const label = __("Translate Arabic");
	frm.remove_custom_button(label, __("Retail"));

	const field = frm.fields_dict.custom_arabic_item_name;
	if (!field || !field.$wrapper) return;

	field.$wrapper.find("button").filter(function () {
		const text = ($(this).text() || "").trim();
		return text === label || text === "Translate Arabic";
	}).remove();
}
